macro_rules! take_stderr {
    () => {
        # [doc = " `STDERR_FILENO`—Standard error, owned."] # [doc = ""] # [doc = " This is similar to [`stderr`], however it returns an `OwnedFd` which closes"] # [doc = " standard output when it is dropped."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Safe std-using Rust code is permitted to assume that the stderr file"] # [doc = " descriptor is always valid. This function returns an `OwnedFd` which will"] # [doc = " close the stderr file descriptor when dropped."] # [doc = ""] # [doc = " # Other hazards"] # [doc = ""] # [doc = " This has the same hazards as [`stderr`]."] # [doc = ""] # [doc = " And, when the `OwnedFd` is dropped, subsequent newly created file"] # [doc = " descriptors may unknowingly reuse the stderr file descriptor number, which"] # [doc = " may break common assumptions, so it should typically only be dropped at the"] # [doc = " end of a program when no more file descriptors will be created."] # [doc = ""] # [doc = " # References"] # [doc = "  - [POSIX]"] # [doc = "  - [Linux]"] # [doc = "  - [FreeBSD]"] # [doc = "  - [NetBSD]"] # [doc = "  - [OpenBSD]"] # [doc = "  - [DragonFly BSD]"] # [doc = "  - [illumos]"] # [doc = "  - [glibc]"] # [doc = ""] # [doc = " [POSIX]: https://pubs.opengroup.org/onlinepubs/9799919799/functions/stderr.html"] # [doc = " [Linux]: https://man7.org/linux/man-pages/man3/stderr.3.html"] # [doc = " [FreeBSD]: https://man.freebsd.org/cgi/man.cgi?query=stderr&sektion=4"] # [doc = " [NetBSD]: https://man.netbsd.org/stderr.4"] # [doc = " [OpenBSD]: https://man.openbsd.org/stderr.4"] # [doc = " [DragonFly BSD]: https://man.dragonflybsd.org/?command=stderr&section=4"] # [doc = " [illumos]: https://illumos.org/man/4FS/stderr"] # [doc = " [glibc]: https://sourceware.org/glibc/manual/latest/html_node/Standard-Streams.html#index-stderr"] # [doc (alias = "STDERR_FILENO")] # [inline] pub unsafe fn take_stderr () -> OwnedFd { backend :: fd :: OwnedFd :: from_raw_fd (c :: STDERR_FILENO as RawFd) }
    };
}

take_stderr!();